    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,29,'Section D','"vii"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,30,'Section E','"ii"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,31,'Section F','"iii"'::jsonb);
