  INSERT INTO ielts_parts (section_id,part_number,context) VALUES (v_sec,3,'Section 3 — Value Survey') RETURNING id INTO v_part;
  INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,1,21,25,'mcq_single','Choose the correct letter, A, B or C.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,21,'According to James and Anna, the Value Survey measured the cost of houses by calculating','[{"letter":"A","text":"the total price of building a new house."},{"letter":"B","text":"the size of house a typical family can afford."},{"letter":"C","text":"the price of houses compared to average income."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,22,'Anna says the Value Survey is unusual because','[{"letter":"A","text":"it compares prices in different cities."},{"letter":"B","text":"it is the oldest survey of its kind."},{"letter":"C","text":"it publishes its results annually."}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,23,'The students decide that New Zealand house prices are high because of','[{"letter":"A","text":"the cost of construction materials."},{"letter":"B","text":"the shortage of builders."},{"letter":"C","text":"the rules concerning land use."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,24,'When the students talk about transport they are','[{"letter":"A","text":"concerned there is no plan."},{"letter":"B","text":"worried about rising costs."},{"letter":"C","text":"alarmed by increasing congestion."}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,25,'The students agree that the next Value Survey will','[{"letter":"A","text":"compare a wider number of locations."},{"letter":"B","text":"indicate a future trend in house prices."},{"letter":"C","text":"advise against regulation of house prices."}]'::jsonb,'"B"'::jsonb);
  INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,2,26,30,'paragraph_matching','What aspect of the Value Survey did each of the following people criticize? Choose FIVE answers from the box, A-G.','{"items":[{"letter":"A","text":"organization of final text"},{"letter":"B","text":"researchers'' qualifications"},{"letter":"C","text":"period covered"},{"letter":"D","text":"level of funding"},{"letter":"E","text":"lack of public access to full information"},{"letter":"F","text":"old-fashioned systems of data analysis"},{"letter":"G","text":"way of defining home-buyers'' wealth"}],"paragraph_labels":["A","B","C","D","E","F","G"]}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,26,'Andrew Coleman','"C"'::jsonb);
